"""Audit only real face-loaded outputs; preserve failed original criteria."""
from run_aircraft_a31 import *
from audit_aircraft_a05 import vtk
from assess_aircraft_a23_reader_precision import printed_bound
import subprocess

def preserve():
    import audit_aircraft_a27 as old
    s=inspect.getsource(old.preserve).replace('preservation_A27','preservation_A31');ns=dict(globals());exec(compile(s,__file__+'::preserve','exec'),ns);ns['preserve']();dump(OUT/'preservation_reader_derivation.json',{'source':rel(Path(old.__file__)),'source_sha256':streamsha(Path(old.__file__)),'derived_source':s,'old_files_only_read':True})

def fields():
    guard();dest=OUT/'native_fields_review.json';assert not dest.exists();assert (OUT/'native_case_summary.json').exists();samples=[];inputs=[]
    for d in sorted((OUT/'w0').iterdir()):
        g=read(d/'generation.json');X=np.asarray(g['nodes_mm']);B=np.asarray(g['bricks']);pids=np.asarray(g['brick_parts']);n=g['name'];s=(d/(n+'_0000.rad')).read_text();boundaries=set(g['bottom_node_ids']+g['top_node_ids']);actual={int(q) for q in re.findall(r'^/GRNOD/NODE/(\d+)',s,re.M)};checks={'only_boundary_constrained':actual==boundaries,'all_interior_free':len(actual)==2*(g['mesh_n']+1)**2 and len(actual)<len(X),'source_core_card':'\n'.join(parent()['/MAT/LAW28/28'])+'\n' in s,'declared_skin_card':'\n'.join(skin.law12_card())+'\n' in s,'known_mass':abs(g['known_mass_g']-.2214)<1e-10,'native_frames':read(d/'native_frame_gate.json')['pass']};inputs.append({'case':d.name,'boundary_nodes':len(boundaries),'free_interior_nodes':len(X)-len(boundaries),'checks':checks,'pass':all(checks.values())});native=sorted(p for p in d.glob(n+'A*') if re.fullmatch(re.escape(n)+r'A\d{3}',p.name));assert native
        for p in sorted(set([native[0],native[len(native)//2],native[-1]])):
            ad=OUT/'native_field_audit'/d.name;ad.mkdir(parents=True,exist_ok=True);v=ad/(p.name+'.vtk');assert not v.exists();res=subprocess.run([str(RUNTIME/'anim_to_vtk_win64.exe'),str(p)],capture_output=True,text=True,check=True,timeout=180);v.write_text(res.stdout,encoding='utf-8');q=vtk(res.stdout);order=np.argsort(q['NODE_ID']);pts=q['points'].reshape(-1,3)[order];disp=q['Displacement'].reshape(-1,3)[order];vel=q['Velocity'].reshape(-1,3)[order];bound=printed_bound(pts)+printed_bound(disp)+4*np.finfo(np.float32).eps*np.maximum.reduce([abs(pts),abs(disp),abs(X)])+1e-8;checks={'ids':bool(np.array_equal(q['NODE_ID'][order],np.arange(1,len(X)+1))),'finite':bool(np.isfinite(pts).all() and np.isfinite(disp).all() and np.isfinite(vel).all()),'identity_with_printing_bound':bool(np.all(abs(pts-X-disp)<=bound)),'no_eroded_elements':bool(np.all(q['EROSION_STATUS']==1))};samples.append({'case':d.name,'time_ms':q['time'],'native':rel(p),'native_sha256':streamsha(p),'vtk':rel(v),'vtk_sha256':streamsha(v),'checks':checks,'pass':all(checks.values())})
    dump(dest,{'created_utc':now(),'samples':samples,'pass':all(x['pass'] for x in samples),'old_native_reruns':0});dump(OUT/'face_boundary_review.json',{'created_utc':now(),'cases':inputs,'pass':all(x['pass'] for x in inputs),'physical_perfect_bond_remains_hypothesis':True})

def review():
    guard();dest=OUT/'sandwich_qualification_review.json';assert not dest.exists();rows=read(OUT/'native_case_summary.json')['cases'];assert len(rows)==9;h=dict(np.load(OUT/'w0/SHEAR_XZ_N12/histories_SI.npz'));h2=dict(np.load(OUT/'w0/SHEAR_XZ_N12_HALF/histories_SI.npz'));mask=(h['time_ms']>=h2['time_ms'][0])&(h['time_ms']<=h2['time_ms'][-1]);T=h['time_ms'][mask];ed=float(abs(h['IE_J'][mask]-np.interp(T,h2['time_ms'],h2['IE_J'])).max());fd=float(abs(h['top_internal_force_N'][mask]-np.interp(T,h2['time_ms'],h2['top_internal_force_N'])).max());ratio=float(np.median(h2['time_step_ms'][1:])/np.median(h['time_step_ms'][1:]));ref=read(OUT/'references/SHEAR_XZ_N12.json');dt={'actual_dt_ratio':ratio,'IE_difference_J':ed,'reaction_difference_N':fd,'checks':{'actually_shorter':ratio<.6,'energy_converges':bool(ed<.002*ref['energy_J']+1e-7),'reaction_converges':bool(fd<.002*abs(ref['top_reaction_N'])+1e-5)}};mesh=[]
    for mode_name in ['SHEAR_XZ','SHEAR_YZ','NORMAL_TENSION','NORMAL_COMPRESSION']:
        a=read(OUT/'w0'/f'{mode_name}_N6/review.json');b=read(OUT/'w0'/f'{mode_name}_N12/review.json');ra=read(OUT/'references'/f'{mode_name}_N6.json');rb=read(OUT/'references'/f'{mode_name}_N12.json');native=abs(a['native_elastic_comparison_J']-b['native_elastic_comparison_J'])/b['native_elastic_comparison_J'];static=abs(ra['energy_J']-rb['energy_J'])/rb['energy_J'];mesh.append({'mode':mode_name,'native_IE_change_fraction':native,'independent_static_IE_change_fraction':static,'checks':{'native_converges':native<.05,'independent_converges':static<.05},'pass':native<.05 and static<.05,'coarse_original_gate':a['pass'],'fine_original_gate':b['pass']})
    candidates=[r for r in rows if '_N12' in r['case']];f=read(OUT/'native_fields_review.json');b=read(OUT/'face_boundary_review.json');checks={'all_fine_original_gates':all(x['pass'] for x in candidates),'native_fields':f['pass'],'true_free_interior':b['pass'],'time_refinement':all(dt['checks'].values()),'spatial_refinement':all(x['pass'] for x in mesh)};dump(dest,{'created_utc':now(),'cases':rows,'candidate_cases':[r['case'] for r in candidates],'checks':checks,'refinement':dt,'mesh':mesh,'fine_face_loaded_scope_pass':all(checks.values()),'coarse_failed_gates_retained':True,'physical_debonding_or_fracture_qualified':False,'whole_insertion_ready':False,'objective1_complete':False});print({'A31_review':checks,'fine_scope_pass':all(checks.values())},flush=True)

if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('action',choices=['preserve','fields','review']);globals()[p.parse_args().action]()
